MultiLanguageSpellData['it'][467024] = {name = "Contenitore di Kaja'Cola", additional_info = "[q]Le Curiosità Smarrite hanno una probabilità del 35% di contenere 1 Kaja'Cola e, una volta per Scorribanda, Brann evoca un Pacchetto da 6 di Kaja'Cola quando crea un falò.\n\n Ci sono vari gusti di Kaja'Cola, ciascuno dei quali ha un effetto diverso che si attiva quando la si raccoglie."}
MultiLanguageSpellData['it'][467026] = {name = "Granata Rimbalzante Globomagnetica", additional_info = "[q]Brann ha una probabilità in combattimento di lanciare una Granata Rimbalzante Globomagnetica contro un bersaglio nemico, infliggendo moderati danni da natura e con una probabilità del 20% di stordirlo per 1.5 s. Inoltre, c'è una probabilità del 25% che la granata rimbalzi su un nuovo bersaglio.\n\n Se la granata rimbalza sui membri del gruppo non è dannosa."}
MultiLanguageSpellData['it'][467029] = {name = "Matrice di Conversione d'Impatto", additional_info = "[q]Quando entra in combattimento, Brann attiva la matrice di conversione per 10 s. Una piccola percentuale di tutti i danni inflitti dal gruppo durante questo lasso di tempo viene convertita in un attributo primario e condivisa con i membri del gruppo.\n\n Dopo che la matrice di conversione si è disattivata, il beneficio all'attributo primario persiste per 10 s. Può verificarsi solo una volta ogni 2 min."}
MultiLanguageSpellData['it'][467031] = {name = "Flusso di Sangue Nero", additional_info = "Portata illimitata\nIstantaneo\n[q]Il Sangue Nero filtra dal soffitto della struttura, infliggendo 14 danni da ombra ogni 0.5 s."}
