MultiLanguageSpellData['it'][474572] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nContenitore di Kaja'Cola\n[q]Le Curiosità Smarrite hanno una probabilità del 35% di contenere 1 Kaja'Cola e, una volta per Scorribanda, Brann evoca un Pacchetto da 6 di Kaja'Cola quando crea un falò.\n\n Ci sono vari gusti di Kaja'Cola, ciascuno dei quali ha un effetto diverso che si attiva quando la si raccoglie.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474573] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nMagnete Comicamente Grande\n[q]Quando Brann usa Raccolta Attrezzi , c'è una probabilità del 100 % che il Rivestimento Scartato si magnetizzi, fornendo ai membri del gruppo uno scudo che assorbe danni subiti pari al 5 % della loro salute massima e che si rigenera quando non si è in combattimento.\n\n Raccolta Attrezzi\nBrann usa i suoi attrezzi di raccolta per aiutare i personaggi a trovare oro, erbe, minerali, pesci, pelli e tesori aggiuntivi.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474574] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nEquipaggiamento Razzo a Biocarburante\n[q]I membri del gruppo sono equipaggiati con l' Equipaggiamento Razzo a Biocarburante .\n\n Biocarburante\n Ogni nemico ucciso alimenta il Equipaggiamento Razzo a Biocarburante , aumentando la velocità di movimento del 2% e la celerità del 2% per 10 s. Si accumula fino a 10 volte.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474576] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nBiostampante Tridimensionale\n[q]Infliggere danni a una creatura d'élite con meno del 40% della salute massima ne crea una copia imperfetta con il 50% della potenza che combatte al tuo fianco. 1 sola copia può esistere alla volta.\n\n Un malfunzionamento nel dispositivo potrebbe creare delle copie imperfette del tuo compagno.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474577] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nPilone di Sovraccarico\n[q]Dopo 30 s di combattimento, i danni inflitti o le cure fornite dai membri del gruppo e da Brann aumentano del 5% per 20 s. Può attivarsi solo una volta per combattimento.\n\nHai già questo Reperto nella tua collezione."}
