MultiLanguageSpellData['it'][474599] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nKit da Costruzione Rapida del Meccasauro\n[q]L' Uovo Epico di Brann ora ospita 1 meccasauri che provocano i nemici per ( 4000 / 1000) s mentre sono nell'uovo.\n\n Oltre alle consuete abilità, i meccasauri colpiscono periodicamente il terreno, infliggendo moderati danni da fuoco suddivisi tra i nemici vicini. I nemici affetti esplodono dopo 5 s, subendo moderati danni da fuoco.\n\n Uovo Epico di Brann\nBrann evoca un uovo di gigantosauro. E spera che si schiuda.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474600] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nDistributore Automatico di Calciobombe\n[q]Gli incantesimi e le abilità di Brann hanno una probabilità di rilasciare sul campo 2 calciobombe per 10 s.\n\n Passare su una calciobomba la calcia verso un bersaglio nemico, infliggendo ingenti danni da fuoco a tutti i nemici in un raggio di 6 m.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474601] = {name = "Aggiunta", additional_info = "1.5 s di lancio\nReagenti:\nMatrice di Conversione d'Impatto\n[q]Quando entra in combattimento, Brann attiva la matrice di conversione per 10 s. Una piccola percentuale di tutti i danni inflitti dal gruppo durante questo lasso di tempo viene convertita in un attributo primario e condivisa con i membri del gruppo.\n\n Dopo che la matrice di conversione si è disattivata, il beneficio all'attributo primario persiste per 10 s. Può verificarsi solo una volta ogni 2 min.\n\nHai già questo Reperto nella tua collezione."}
MultiLanguageSpellData['it'][474602] = {name = "Cannone Ruggente Esplosivo", additional_info = "Portata di 60 m\nIstantaneo\n[q]Motorendo segue un bersaglio durante la carica, quindi si blocca in posizione e si prepara a sparare. Una volta pronto, spara un raggio per 3 s. Il raggio infligge 66606435 danni da fuoco ogni 0.1 s ai personaggi che colpisce, annientandoli."}
