MultiLanguageSpellData['it'][1215722] = {name = "Ladro Scaltrezza, Set di Classe 11.1, 4 Pezzi", additional_info = "[q0][Item Effect][q]Durante Danza dell'Ombra, non è possibile perdere Serie Vincente! , si ottiene un accumulo aggiuntivo di Serie Vincente! ogni volta che se ne ottiene 1 accumulo e si infligge il 2% di danni da ombra aggiuntivi per ogni accumulo di Serie Vincente! ."}
MultiLanguageSpellData['it'][1215724] = {name = "Ladro Assassinio, Set di Classe 11.1, 4 Pezzi", additional_info = "[q0][Item Effect][q]Quando si perde Serie Vincente! , di ha una probabilità di ottenere invece il numero massimo di accumuli di Serie Vincente! per 4s. L'effetto non può essere dissolto e ha un effetto aumentato del 50% quando si è immuni agli effetti di dissolvimento."}
MultiLanguageSpellData['it'][1215725] = {name = "Ladro Fuorilegge, Set di Classe 11.1, 4 Pezzi", additional_info = "[q0][Item Effect][q]Roulette Assassina ha una probabilità aggiuntiva del 40% di fornire dei potenziamenti aggiuntivi in combattimento e inoltre fornisce 1 accumulo di Serie Vincente! per ogni potenziamento di combattimento fornito.\n\n Gli accumuli applicati da Roulette Assassina possono eccedere il limite massimo di accumuli per Serie Vincente! di 5."}
MultiLanguageSpellData['it'][1215726] = {name = "Cavaliere della Morte Empietà, Set di Classe 11.1, 2 Pezzi", additional_info = "[q0][Item Effect]Circa 10 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare Serie Vincente! , aumentando i danni inflitti da Spira Mortale ed Epidemia del 45%. Si accumula fino a 10 volte. Spira Mortale ed Epidemia hanno una probabilità del 15% di consumare Serie Vincente! ."}
MultiLanguageSpellData['it'][1215727] = {name = "Cavaliere della Morte Gelo, Set di Classe 11.1, 2 Pezzi", additional_info = "[q0][Item Effect]Circa 10 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare Serie Vincente! , aumentando i danni inflitti da Assalto del Gelo e Avanzata Glaciale del 4%. Si accumula fino a 6 volte. Assalto del Gelo e Avanzata Glaciale hanno una probabilità del 7% di consumare Serie Vincente!"}
MultiLanguageSpellData['it'][1215728] = {name = "Cavaliere della Morte Empietà, Set di Classe 11.1, 4 Pezzi", additional_info = "[q0][Item Effect][q]Lanciare Trasformazione Oscura fornisce fino a 10 accumuli di Serie Vincente! . Mentre Trasformazione Oscura è attiva, l'efficacia di Serie Vincente! aumenta del 100% e non ha più alcuna probabilità di azzerarsi."}
MultiLanguageSpellData['it'][1215729] = {name = "Cavaliere della Morte Gelo, Set di Classe 11.1, 4 Pezzi", additional_info = "[q0][Item Effect][q]Serie Vincente! fornisce ad Assalto del Gelo e Avanzata Glaciale una probabilità del 8% di lanciare Falce del Signore del Gelo per ogni accumulo al 30% dell'efficacia. Perdere Serie Vincente! scatena in te una Frenesia Assassina, facendoti lanciare Falce del Signore del Gelo al 100% dell'efficacia e aumentando la maestria del (6 * $mastery)% per 6 s. Inoltre, i danni inflitti da Falce del Signore del Gelo aumentano del 40% contro il primo bersaglio colpito."}
MultiLanguageSpellData['it'][1215730] = {name = "Cacciatore Sopravvivenza, Set di Classe 11.1, 2 Pezzi", additional_info = "[q0][Item Effect]Circa 10 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare Serie Vincente! , aumentando i danni inflitti da Bomba di Fuocobrado del 3%. Si accumula fino a 6 volte.\n Bomba di Fuocobrado ha una probabilità del 15% di porre fine a Serie Vincente! .\n(Possibilità di Apparire:15%)"}
MultiLanguageSpellData['it'][1215731] = {name = "Cacciatore di Demoni Rovina, Set di Classe 11.1, 2 Pezzi", additional_info = "[q0][Item Effect]Circa 15 apparenze ogni minuto\n[q]Gli incantesimi e le abilità hanno una probabilità di attivare Serie Vincente! , aumentando i danni inflitti da Lame Danzanti e Assalto del Caos del 3%. Si accumula fino a 10 volte. Lame Danzanti e Assalto del Caos hanno una probabilità del 15% di consumare Serie Vincente!"}
MultiLanguageSpellData['it'][1215732] = {name = "Sacrificio Necessario", additional_info = "[q0][Item Effect][q]Serie Vincente! persiste per 8 s dopo essere stata rimossa da Lame Danzanti o Assalto del Caos.\n\n Attivare la Forma Demoniaca sacrifica tutti gli accumuli di Serie Vincente! per aumenta la probabilità di critico del 2% per ogni accumulo consumato. Dura 15 s."}
